REFS['billing-split-function-001'] = ('refactoring', 'billing', {
    'src/billing/invoice.py': '"""Pricing an invoice.\n\n``price_invoice(lines)`` takes ``(unit_price_cents, quantity)`` pairs\nand returns a dict with ``subtotal``, ``discount``, ``tax`` and\n``total`` in cents. A subtotal of 10 000 cents or more earns a 5 %\ndiscount; tax is 23 % of the discounted amount, rounded half away\nfrom zero to the nearest cent.\n"""\n\nfrom __future__ import annotations\n\nfrom billing.tax import tax_amount\nfrom billing.totals import discount, subtotal\n\n\ndef price_invoice(lines: list[tuple[int, int]]) -> dict:\n    """Price the invoice under the rules above."""\n    sub = subtotal(lines)\n    disc = discount(sub)\n    taxable = sub - disc\n    tax = tax_amount(taxable)\n    return {"subtotal": sub, "discount": disc, "tax": tax, "total": taxable + tax}',  # noqa: E501
    'src/billing/tax.py': '"""Tax on a taxable amount."""\n\nfrom __future__ import annotations\n\nfrom decimal import ROUND_HALF_UP, Decimal\n\n\ndef tax_amount(taxable_cents: int) -> int:\n    """23 % of the taxable amount, half away from zero."""\n    return int(\n        (Decimal(taxable_cents) * Decimal("0.23")).quantize(\n            Decimal("1"), rounding=ROUND_HALF_UP\n        )\n    )',  # noqa: E501
    'src/billing/totals.py': '"""Subtotal and discount for an invoice."""\n\nfrom __future__ import annotations\n\nfrom decimal import ROUND_HALF_UP, Decimal\n\n\ndef subtotal(lines: list[tuple[int, int]]) -> int:\n    """The sum of ``unit_price * quantity`` over the lines."""\n    return sum(unit_price * quantity for unit_price, quantity in lines)\n\n\ndef discount(subtotal_cents: int) -> int:\n    """The tier discount: 5 % from 10 000 cents, half away from zero."""\n    if subtotal_cents < 10_000:\n        return 0\n    return int(\n        (Decimal(subtotal_cents) * Decimal("0.05")).quantize(\n            Decimal("1"), rounding=ROUND_HALF_UP\n        )\n    )',  # noqa: E501
})

