REFS['csvkit-quoted-field-001'] = ('debugging', 'csvkit', {
    'src/csvkit/parser.py': '"""Parsing CSV text into rows of fields.\n\nThe format is the usual one: rows are separated by newlines, fields by\ncommas, and a field may be quoted with double quotes. Inside a quoted\nfield a comma is data, not a separator, and two double quotes stand for\none literal quote.\n"""\n\nfrom __future__ import annotations\n\n\ndef parse_csv(text: str) -> list[list[str]]:\n    """Parse ``text`` into a list of rows, each a list of fields."""\n    rows: list[list[str]] = []\n    for line in text.splitlines():\n        if line == "":\n            continue\n        rows.append(_parse_row(line))\n    return rows\n\n\ndef _parse_row(line: str) -> list[str]:\n    fields: list[str] = []\n    current: list[str] = []\n    in_quotes = False\n    index = 0\n    while index < len(line):\n        char = line[index]\n        if in_quotes:\n            if char == \'"\':\n                if index + 1 < len(line) and line[index + 1] == \'"\':\n                    current.append(\'"\')\n                    index += 2\n                    continue\n                in_quotes = False\n            else:\n                current.append(char)\n        elif char == \'"\':\n            in_quotes = True\n        elif char == ",":\n            fields.append("".join(current))\n            current = []\n        else:\n            current.append(char)\n        index += 1\n    fields.append("".join(current))\n    return fields',  # noqa: E501
})

REFS['dates-month-boundary-001'] = ('debugging', 'dates', {
    'src/dates/months.py': '"""Moving a month by a number of months.\n\nMonths are numbered 1 to 12. Adding months crosses year boundaries:\nDecember plus one month is January of the next year, and January minus\none month is December of the previous year.\n"""\n\nfrom __future__ import annotations\n\n\ndef add_months(year: int, month: int, n: int) -> tuple[int, int]:\n    """Return ``(year, month)`` moved by ``n`` months (``n`` may be negative)."""\n    if not 1 <= month <= 12:\n        raise ValueError(f"month must be between 1 and 12, got {month}")\n    index = (year * 12 + (month - 1)) + n\n    return index // 12, index % 12 + 1',  # noqa: E501
})

