REFS['fetcher-open-redirect-001'] = ('security', 'fetcher', {
    'src/fetcher/client.py': '"""Fetching a URL through an injected transport.\n\n``fetch(url, transport)`` calls ``transport(url)`` which returns\n``(status, headers, body)``. A redirect (status 301, 302, 303, 307 or\n308 with a ``Location`` header) is followed, up to five times. The\nfetcher must never fetch an internal or private host, neither directly\nnor through a redirect: such a URL is refused with :class:`ValueError`.\n"""\n\nfrom __future__ import annotations\n\nimport ipaddress\nfrom collections.abc import Callable\nfrom urllib.parse import urlparse\n\nREDIRECT_STATUSES = {301, 302, 303, 307, 308}\nMAX_REDIRECTS = 5\n\n\ndef _is_internal(host: str) -> bool:\n    host = host.lower().rstrip(".")\n    if host == "localhost" or host.endswith(".localhost"):\n        return True\n    try:\n        address = ipaddress.ip_address(host)\n    except ValueError:\n        return False\n    return (\n        address.is_private\n        or address.is_loopback\n        or address.is_link_local\n        or address.is_reserved\n        or address.is_multicast\n        or address.is_unspecified\n    )\n\n\ndef _check(url: str) -> None:\n    host = urlparse(url).hostname or ""\n    if _is_internal(host):\n        raise ValueError(f"refusing to fetch internal host: {url!r}")\n\n\ndef fetch(url: str, transport: Callable) -> str:\n    """Fetch ``url`` through ``transport`` and return the body."""\n    current = url\n    for _ in range(MAX_REDIRECTS + 1):\n        _check(current)\n        status, headers, body = transport(current)\n        if status in REDIRECT_STATUSES and "Location" in headers:\n            current = headers["Location"]\n            continue\n        return body\n    raise ValueError("too many redirects")',  # noqa: E501
})

REFS['fib-memo-001'] = ('performance', 'fibkit', {
    'src/fibkit/memo.py': '"""The memoized Fibonacci: each value computed once."""\n\nfrom __future__ import annotations\n\nfrom functools import lru_cache\n\n\n@lru_cache(maxsize=None)\ndef fib(n: int) -> int:\n    """The n-th Fibonacci number, memoized."""\n    if n < 0:\n        raise ValueError("n must not be negative")\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)',  # noqa: E501
})

REFS['filebox-path-traversal-001'] = ('security', 'filebox', {
    'src/filebox/files.py': '"""Reading text files from a base directory.\n\n``read_text(base_dir, name)`` reads the file ``name`` from inside\n``base_dir`` and returns its text. The name is a relative path: the\nreader must never return a file outside the base directory, however the\nname is written.\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\n\ndef read_text(base_dir: Path, name: str) -> str:\n    """Read ``name`` from inside ``base_dir`` and return its text."""\n    if Path(name).is_absolute():\n        raise ValueError(f"name must be relative: {name!r}")\n    base = Path(base_dir).resolve()\n    path = (base / name).resolve()\n    if path != base and base not in path.parents:\n        raise ValueError(f"name escapes the base directory: {name!r}")\n    return path.read_text(encoding="utf-8")',  # noqa: E501
})

