REFS['indexer-stale-entry-001'] = ('debugging', 'indexer', {
    'src/indexer/index.py': '"""Indexing documents by term.\n\nA document is a set of terms. Searching returns the ids of the live\ndocuments that contain the term, sorted. Deleting a document removes it\nfrom the index entirely: a deleted document must never be found again,\nunless it is added again.\n"""\n\nfrom __future__ import annotations\n\n\nclass Indexer:\n    """Documents by term, with deletion."""\n\n    def __init__(self) -> None:\n        self._docs: dict[str, set[str]] = {}\n        self._index: dict[str, set[str]] = {}\n\n    def add(self, doc_id: str, terms: set[str]) -> None:\n        """Index a document, replacing any previous version of it."""\n        if doc_id in self._docs:\n            self.delete(doc_id)\n        self._docs[doc_id] = set(terms)\n        for term in terms:\n            self._index.setdefault(term, set()).add(doc_id)\n\n    def delete(self, doc_id: str) -> None:\n        """Remove a document from the index entirely."""\n        terms = self._docs.pop(doc_id, None)\n        if terms is None:\n            return\n        for term in terms:\n            holders = self._index.get(term)\n            if holders is not None:\n                holders.discard(doc_id)\n                if not holders:\n                    del self._index[term]\n\n    def search(self, term: str) -> list[str]:\n        """The sorted ids of live documents containing ``term``."""\n        return sorted(self._index.get(term, set()) & set(self._docs))',  # noqa: E501
})

REFS['inventory-repository-001'] = ('architecture', 'inventory', {
    'src/inventory/inventory.py': '"""Tracking stock quantities.\n\n``Inventory.add(name, qty)`` stocks ``qty`` more of ``name``,\n``remove(name)`` drops the item, ``quantity(name)`` returns its\nquantity (0 when absent), ``total_items()`` sums every quantity, and\n``names()`` lists the stocked names sorted. Names must be non-empty\nand quantities must not be negative.\n"""\n\nfrom __future__ import annotations\n\nfrom inventory.storage import InventoryStore\nfrom inventory.validation import validate_item\n\n\nclass Inventory:\n    """Stock quantities per item name."""\n\n    def __init__(self) -> None:\n        self._store = InventoryStore()\n\n    def add(self, name: str, qty: int) -> None:\n        """Stock ``qty`` more of ``name``."""\n        validate_item(name, qty)\n        self._store.add(name, qty)\n\n    def remove(self, name: str) -> None:\n        """Drop ``name`` from the stock."""\n        self._store.remove(name)\n\n    def quantity(self, name: str) -> int:\n        """The quantity of ``name``, or 0 when absent."""\n        return self._store.quantity(name)\n\n    def total_items(self) -> int:\n        """The sum of every quantity."""\n        return self._store.total_items()\n\n    def names(self) -> list[str]:\n        """The stocked names, sorted."""\n        return self._store.names()',  # noqa: E501
    'src/inventory/storage.py': '"""Storing stock quantities."""\n\nfrom __future__ import annotations\n\n\nclass InventoryStore:\n    """Quantities per item name, in a dict."""\n\n    def __init__(self) -> None:\n        self._stock: dict[str, int] = {}\n\n    def add(self, name: str, qty: int) -> None:\n        """Stock ``qty`` more of ``name``."""\n        self._stock[name] = self._stock.get(name, 0) + qty\n\n    def remove(self, name: str) -> None:\n        """Drop ``name`` from the stock."""\n        self._stock.pop(name, None)\n\n    def quantity(self, name: str) -> int:\n        """The quantity of ``name``, or 0 when absent."""\n        return self._stock.get(name, 0)\n\n    def total_items(self) -> int:\n        """The sum of every quantity."""\n        return sum(self._stock.values())\n\n    def names(self) -> list[str]:\n        """The stocked names, sorted."""\n        return sorted(self._stock)',  # noqa: E501
    'src/inventory/validation.py': '"""Validating inventory input."""\n\nfrom __future__ import annotations\n\n\ndef validate_item(name: str, qty: int) -> None:\n    """Raise ``ValueError`` for an empty name or a negative quantity."""\n    if not name.strip():\n        raise ValueError("name must not be empty")\n    if qty < 0:\n        raise ValueError("qty must not be negative")',  # noqa: E501
})

REFS['inverted-index-001'] = ('performance', 'searchkit', {
    'src/searchkit/index.py': '"""An inverted index: word -> document ids."""\n\nfrom __future__ import annotations\n\n\ndef build_index(docs: list[str]) -> dict[str, list[int]]:\n    """Map each word to the ids of the documents containing it."""\n    index: dict[str, list[int]] = {}\n    for doc_id, doc in enumerate(docs):\n        for word in set(doc.split()):\n            index.setdefault(word, []).append(doc_id)\n    return index\n\n\ndef search(index: dict[str, list[int]], term: str) -> list[int]:\n    """The ids of the documents containing ``term``."""\n    return list(index.get(term, []))',  # noqa: E501
})

REFS['pipeline-stage-order-001'] = ('debugging', 'pipeline', {
    'src/pipeline/pipeline.py': '"""Stages in order, with a retry from the failed stage.\n\nStages are callables applied in the order they were added. When a stage\nraises, the pipeline retries once from the failed stage: stages before\nit have already done their work and must not run again.\n"""\n\nfrom __future__ import annotations\n\nfrom collections.abc import Callable\n\n\nclass Pipeline:\n    """An ordered list of stages with a single retry."""\n\n    def __init__(self) -> None:\n        self._stages: list[tuple[str, Callable]] = []\n\n    def add_stage(self, name: str, fn: Callable) -> None:\n        """Append a stage to the end of the pipeline."""\n        self._stages.append((name, fn))\n\n    def run(self, value):\n        """Run the stages in order, retrying once from a failed stage."""\n        current = value\n        for index, (_name, fn) in enumerate(self._stages):\n            try:\n                current = fn(current)\n            except Exception:\n                # Retry once from the failed stage onward.\n                for _retry_name, retry_fn in self._stages[index:]:\n                    current = retry_fn(current)\n                break\n        return current',  # noqa: E501
})

