REFS['plugcore-registry-001'] = ('architecture', 'plugcore', {
    'src/plugcore/plugins.py': '"""Applying named text transforms.\n\n``apply(name, text)`` runs the transform called ``name`` on ``text``:\n``"upper"`` uppercases, ``"lower"`` lowercases, ``"reverse"`` reverses.\nAn unknown name raises ``ValueError``. Transforms live in a registry,\nso new ones register without touching this dispatch.\n"""\n\nfrom __future__ import annotations\n\nfrom plugcore import registry\n\n\ndef _upper(text: str) -> str:\n    return text.upper()\n\n\ndef _lower(text: str) -> str:\n    return text.lower()\n\n\ndef _reverse(text: str) -> str:\n    return text[::-1]\n\n\nregistry.register("upper", _upper)\nregistry.register("lower", _lower)\nregistry.register("reverse", _reverse)\n\n\ndef apply(name: str, text: str) -> str:\n    """Run the transform ``name`` on ``text``."""\n    return registry.get(name)(text)',  # noqa: E501
    'src/plugcore/registry.py': '"""A registry of named text transforms."""\n\nfrom __future__ import annotations\n\nfrom typing import Callable\n\n\nclass PluginRegistry:\n    """Named transforms, registered by name."""\n\n    def __init__(self) -> None:\n        self._transforms: dict[str, Callable[[str], str]] = {}\n\n    def register(self, name: str, func: Callable[[str], str]) -> None:\n        """Register ``func`` under ``name``."""\n        self._transforms[name] = func\n\n    def get(self, name: str) -> Callable[[str], str]:\n        """The transform called ``name``; ``ValueError`` when unknown."""\n        try:\n            return self._transforms[name]\n        except KeyError:\n            raise ValueError(f"unknown transform: {name!r}") from None\n\n    def names(self) -> list[str]:\n        """The registered names, sorted."""\n        return sorted(self._transforms)\n\n\n_default = PluginRegistry()\n\n\ndef register(name: str, func: Callable[[str], str]) -> None:\n    """Register ``func`` under ``name`` in the default registry."""\n    _default.register(name, func)\n\n\ndef get(name: str) -> Callable[[str], str]:\n    """The transform called ``name`` in the default registry."""\n    return _default.get(name)\n\n\ndef names() -> list[str]:\n    """The names in the default registry, sorted."""\n    return _default.names()',  # noqa: E501
})

REFS['queuekit-deque-migration-001'] = ('refactoring', 'queuekit', {
    'src/queuekit/backend.py': '"""The queue backend: a deque behind a small API."""\n\nfrom __future__ import annotations\n\nfrom collections import deque\n\n\nclass DequeQueue:\n    """A first-in-first-out queue on ``collections.deque``."""\n\n    def __init__(self) -> None:\n        self._items: deque = deque()\n\n    def enqueue(self, value) -> None:\n        """Add ``value`` at the back."""\n        self._items.append(value)\n\n    def dequeue(self):\n        """Take the front value, or ``None`` when empty."""\n        if not self._items:\n            return None\n        return self._items.popleft()\n\n    def __len__(self) -> int:\n        return len(self._items)',  # noqa: E501
    'src/queuekit/queue.py': '"""A FIFO queue.\n\n``enqueue`` adds at the back, ``dequeue`` takes from the front (or\nreturns ``None`` when empty), and ``len`` counts the waiting items.\nThe backend is :class:`queuekit.backend.DequeQueue`.\n"""\n\nfrom __future__ import annotations\n\nfrom queuekit.backend import DequeQueue\n\n\nclass Queue:\n    """A first-in-first-out queue."""\n\n    def __init__(self) -> None:\n        self._backend = DequeQueue()\n\n    def enqueue(self, value) -> None:\n        """Add ``value`` at the back."""\n        self._backend.enqueue(value)\n\n    def dequeue(self):\n        """Take the front value, or ``None`` when empty."""\n        return self._backend.dequeue()\n\n    def __len__(self) -> int:\n        return len(self._backend)',  # noqa: E501
})

