REFS['session-explicit-state-001'] = ('refactoring', 'session', {
    'src/session/state.py': '"""Session state through a default session.\n\nThe module functions delegate to one default :class:`Session`, so\nexisting callers keep working while new code can hold its own\nsessions.\n"""\n\nfrom __future__ import annotations\n\nfrom session.store import Session\n\n_default = Session()\n\n\ndef login(user: str) -> None:\n    """Start a session for ``user`` with an empty cart."""\n    _default.login(user)\n\n\ndef logout() -> None:\n    """End the session and clear the cart."""\n    _default.logout()\n\n\ndef add_to_cart(price_cents: int) -> None:\n    """Add an item priced ``price_cents`` to the cart."""\n    _default.add_to_cart(price_cents)\n\n\ndef cart_total() -> int:\n    """The cart total in cents."""\n    return _default.cart_total()',  # noqa: E501
    'src/session/store.py': '"""An explicit session: user and cart in one object."""\n\nfrom __future__ import annotations\n\n\nclass Session:\n    """One shopping session, independent of every other."""\n\n    def __init__(self) -> None:\n        self._user: str | None = None\n        self._cart: list[int] = []\n\n    def login(self, user: str) -> None:\n        """Start a session for ``user`` with an empty cart."""\n        self._user = user\n        self._cart = []\n\n    def logout(self) -> None:\n        """End the session and clear the cart."""\n        self._user = None\n        self._cart = []\n\n    def add_to_cart(self, price_cents: int) -> None:\n        """Add an item priced ``price_cents`` to the cart."""\n        if self._user is None:\n            raise ValueError("no session: login first")\n        self._cart.append(price_cents)\n\n    def cart_total(self) -> int:\n        """The cart total in cents."""\n        return sum(self._cart)',  # noqa: E501
})

REFS['shopcore-layered-001'] = ('architecture', 'shopcore', {
    'src/shopcore/notifier.py': '"""Announcing orders to customers."""\n\nfrom __future__ import annotations\n\n\ndef notify(order_id: int, total: int) -> str:\n    """The confirmation message for an order."""\n    return f"Order {order_id} confirmed: {total} cents"',  # noqa: E501
    'src/shopcore/pricing.py': '"""Pricing an order."""\n\nfrom __future__ import annotations\n\nfrom decimal import ROUND_HALF_UP, Decimal\n\n\ndef price_total(items: list[tuple[int, int]]) -> int:\n    """The total for ``(unit_price_cents, quantity)`` pairs.\n\n    A subtotal of 10 000 cents or more earns a 5 % discount; shipping\n    is free from 5 000 cents, otherwise 499 cents.\n    """\n    subtotal = sum(price * qty for price, qty in items)\n    if subtotal >= 10_000:\n        discount = int(\n            (Decimal(subtotal) * Decimal("0.05")).quantize(\n                Decimal("1"), rounding=ROUND_HALF_UP\n            )\n        )\n    else:\n        discount = 0\n    shipping = 0 if subtotal >= 5_000 else 499\n    return subtotal - discount + shipping',  # noqa: E501
    'src/shopcore/repository.py': '"""Storing orders in sqlite."""\n\nfrom __future__ import annotations\n\nimport sqlite3\n\n\nclass OrderRepository:\n    """Orders in a sqlite table."""\n\n    def __init__(self, conn: sqlite3.Connection) -> None:\n        self._conn = conn\n        self._conn.execute(\n            "CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY, total INTEGER)"\n        )\n\n    def save(self, total: int) -> int:\n        """Store ``total`` and return the new order id."""\n        cursor = self._conn.execute("INSERT INTO orders (total) VALUES (?)", (total,))\n        return cursor.lastrowid\n\n    def get(self, order_id: int) -> int | None:\n        """The stored total for ``order_id``, or ``None``."""\n        row = self._conn.execute(\n            "SELECT total FROM orders WHERE id = ?", (order_id,)\n        ).fetchone()\n        return row[0] if row else None',  # noqa: E501
    'src/shopcore/shop.py': '"""Placing orders, end to end.\n\n``OrderService.place_order(items)`` takes ``(unit_price_cents,\nquantity)`` pairs, prices the order, stores it, records a\nconfirmation message, and returns a dict with ``order_id`` and\n``total``. The work lives in the pricing, repository and notifier\nlayers.\n"""\n\nfrom __future__ import annotations\n\nimport sqlite3\n\nfrom shopcore.notifier import notify\nfrom shopcore.pricing import price_total\nfrom shopcore.repository import OrderRepository\n\n\nclass OrderService:\n    """Places orders through the pricing, repository and notifier layers."""\n\n    def __init__(self, conn: sqlite3.Connection | None = None) -> None:\n        self._repository = OrderRepository(conn or sqlite3.connect(":memory:"))\n        self.sent_messages: list[str] = []\n\n    def place_order(self, items: list[tuple[int, int]]) -> dict:\n        """Price, store and announce the order; return its id and total."""\n        total = price_total(items)\n        order_id = self._repository.save(total)\n        self.sent_messages.append(notify(order_id, total))\n        return {"order_id": order_id, "total": total}',  # noqa: E501
})

