REFS['sorted-search-001'] = ('performance', 'sortedkit', {
    'src/sortedkit/scan.py': '"""Searching a sorted list.\n\nThe search is a binary search in :mod:`sortedkit.search`; this module\nkeeps the original import path working.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom sortedkit.search import find_position\n\n__all__ = ["find_position"]',  # noqa: E501
    'src/sortedkit/search.py': '"""A binary search over a sorted list."""\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\n\ndef find_position(items: list[Any], target: Any) -> int:\n    """The index of ``target`` in the sorted ``items``, or -1."""\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        if items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1',  # noqa: E501
})

