def _run(work: Path, tests: Path) -> subprocess.CompletedProcess:
    env = {
        **os.environ,
        "PYTHONPATH": str(work / "src"),
        "PYTHONDONTWRITEBYTECODE": "1",
    }
    return subprocess.run(
        [sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", str(tests)],
        cwd=work,
        env=env,
        capture_output=True,
        text=True,
        timeout=300,
    )


@pytest.mark.parametrize("task_id", sorted(REFS))
def test_roadmap_task(task_id: str, tmp_path: Path) -> None:
    category, source, ref_files = REFS[task_id]
    work = tmp_path / "repo"
    shutil.copytree(DATASETS / "_sources" / source, work)
    task_dir = DATASETS / category / task_id

    # The base state must fail the hidden tests...
    result = _run(work, task_dir / "hidden_tests")
    assert result.returncode != 0, (
        f"{task_id}: hidden tests pass on the base fixture"
    )
    # ...while the repository suite passes on the base.
    result = _run(work, work / "tests")
    assert result.returncode == 0, result.stdout + result.stderr

    # Apply the reference solution.
    for rel, content in ref_files.items():
        target = work / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")

    result = _run(work, task_dir / "hidden_tests")
    assert result.returncode == 0, result.stdout + result.stderr
    result = _run(work, task_dir / "public_tests")
    assert result.returncode == 0, result.stdout + result.stderr
    result = _run(work, work / "tests")
    assert result.returncode == 0, result.stdout + result.stderr
